import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Local docs assistant","description":"","frontmatter":{},"headers":[],"relativePath":"ai/docs-assistant.md","filePath":"ai/docs-assistant.md"}'),n={name:"ai/docs-assistant.md"};function o(r,e,l,d,p,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="local-docs-assistant" tabindex="-1">Local docs assistant <a class="header-anchor" href="#local-docs-assistant" aria-label="Permalink to &quot;Local docs assistant&quot;">​</a></h1><p>Explore approved <code>encrypt-rsa</code> templates by choosing a runtime and operation. The assistant selects a template ID with AI SDK, checks that it matches your choices, and displays reviewed example code. It never executes generated code.</p><h2 id="run-without-a-provider-account" tabindex="-1">Run without a provider account <a class="header-anchor" href="#run-without-a-provider-account" aria-label="Permalink to &quot;Run without a provider account&quot;">​</a></h2><p>Complete <a href="./../ai-integrations.html#run-the-examples">AI integration setup</a>, then start the demo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/ai-integrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span></span></code></pre></div><p>Open <code>http://127.0.0.1:3001</code>. The server binds to localhost; set <code>PORT</code> if you need another port. It always uses offline fixtures, so no API key or paid account is needed.</p><ol><li>Choose <strong>Node.js</strong> or <strong>Browser</strong>.</li><li>Choose <strong>Encrypt JSON</strong> or <strong>Sign message</strong>.</li><li>Review the matching template and fill in its application-specific placeholders in your own code.</li></ol><table tabindex="0"><thead><tr><th>Choice</th><th>What the template demonstrates</th></tr></thead><tbody><tr><td>Node.js + JSON</td><td><code>encryptJSON</code> and schema-validated <code>decryptJSON</code></td></tr><tr><td>Browser + JSON</td><td>The same JSON API over Web Crypto in a secure context</td></tr><tr><td>Node.js + signed message</td><td>Signing, trusted key resolution, payload validation, and atomic replay prevention</td></tr><tr><td>Browser + signed message</td><td>Verifying a server-signed message with the expected audience</td></tr></tbody></table><p>The web form accepts only the two public choices. It has no field for keys, chat history, secrets, or free-form prompts. Generated responses must match the strict template schema and requested operation.</p><h2 id="use-the-fixture-cli" tabindex="-1">Use the fixture CLI <a class="header-anchor" href="#use-the-fixture-cli" aria-label="Permalink to &quot;Use the fixture CLI&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/ai-integrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span></span></code></pre></div><p>This prints the default Node.js JSON recommendation and notices without making external calls. The <a href="https://github.com/miladezzat/encrypt-rsa/blob/master/examples/ai-integrations/assistant.mjs" target="_blank" rel="noreferrer">assistant source</a> contains all four templates and selection validation.</p><h2 id="optional-live-cli" tabindex="-1">Optional live CLI <a class="header-anchor" href="#optional-live-cli" aria-label="Permalink to &quot;Optional live CLI&quot;">​</a></h2><p>A separate explicit opt-in can use AI Gateway:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Provide AI_GATEWAY_API_KEY in the server environment, outside source control.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/ai-integrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assistant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --live</span></span></code></pre></div><p>Set <code>AI_MODEL</code> to select an available model; the CLI&#39;s default is <code>openai/gpt-6.1-sol</code>. Model access depends on your account. The live CLI sends the two public enum requirements and may incur provider charges. Keep credentials on the server; never put a provider key in browser code. The web demo stays in fixture mode even when credentials are available.</p><h2 id="use-the-output-correctly" tabindex="-1">Use the output correctly <a class="header-anchor" href="#use-the-output-correctly" aria-label="Permalink to &quot;Use the output correctly&quot;">​</a></h2><p>Approved templates still require your own keys, schema parsers, authentication, storage, and nonce policy. Keep encryption and signing keys separate. Encryption does not hide plaintext submitted to a provider; signatures do not establish truth, prevent prompt injection, or authorize a tool.</p><p>Read <a href="./../json.html">JSON encryption</a> and <a href="./../signed-messages.html">signed messages</a> before adapting the output. Fixture tests verify selection and validation mechanics; they do not prove a live provider&#39;s availability, output quality, or privacy guarantees.</p>`,19)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
